examples.template:
MonarchButton({{trigger}}) { isShown = true }
    .sheet(isPresented: $isShown) {
        VStack(alignment: .leading, spacing: theme.spacing.space4) {
            ScrollView {
                VStack(alignment: .leading, spacing: theme.spacing.space3) {
                    Text("We’ve updated our terms")
                        .monarchTextStyle(.heading)
                        .accessibilityAddTraits(.isHeader)
                    Text("Effective from \(effective.formatted(Date.FormatStyle(date: .long, time: .omitted).locale(locale)))")
                        .monarchTextStyle(.bodySmall)
                        .foregroundStyle(theme.colors.textMuted)
                    Text({{summary.intro}})
                        .monarchTextStyle(.bodySmall)
                        .foregroundStyle(theme.colors.textMuted)
                    VStack(alignment: .leading, spacing: theme.spacing.space1) {
                        Text("• " + {{summary.items.0}})
                        Text("• " + {{summary.items.1}})
                    }
                    .monarchTextStyle(.bodySmall)
                    .foregroundStyle(theme.colors.textMuted)
                    VStack(alignment: .leading, spacing: theme.spacing.space1) {
                        Text("Read the full documents")
                            .monarchTextStyle(.label)
                        if let termsURL {
                        HStack(alignment: .firstTextBaseline, spacing: 0) {
                            Link({{documents.0.label}}, destination: termsURL)
                                .buttonStyle(.monarchLink(.inline))
                            Text(" (version " + {{documents.0.version}} + ")")
                                .foregroundStyle(theme.colors.textMuted)
                        }
                        .monarchTextStyle(.bodySmall)
                        }
                        if let privacyURL {
                        HStack(alignment: .firstTextBaseline, spacing: 0) {
                            Link({{documents.1.label}}, destination: privacyURL)
                                .buttonStyle(.monarchLink(.inline))
                            Text(" (version " + {{documents.1.version}} + ")")
                                .foregroundStyle(theme.colors.textMuted)
                        }
                        .monarchTextStyle(.bodySmall)
                        }
                    }
                }
                .frame(maxWidth: .infinity, alignment: .leading)
            }
            HStack(spacing: theme.spacing.space2) {
                Spacer(minLength: 0)
                MonarchButton({{declineLabel}}, variant: .secondary) { isShown = false }
                MonarchButton("Accept and continue", variant: .primary, isLoading: isAccepting) {
                    isAccepting = true
                    isShown = false
                }
            }
        }
        .foregroundStyle(theme.colors.textDefault)
        .padding(theme.spacing.space4)
        .interactiveDismissDisabled()
        .presentationDetents([.height(460)])
        .presentationBackground(theme.colors.bgSurface)
    }

